// Die Instanzwerte kommen aus sub-einstellungen (Knoten davor) und werden
// in der Data Table pw_config gepflegt (n8n-Oberfläche, "Data Tables").
// HIER stehen nur die FACHLICHEN Einstellungen dieses Workflows: Fristen,
// Tag-Namen, Feldnamen.
const werte = $('Einstellungen holen').first().json;
const pw = (key) => {
  const v = werte[key];
  if (v === undefined || String(v).trim() === '') {
    throw new Error('pw_config: "' + key + '" fehlt oder ist leer; in der n8n-Oberfläche unter "Data Tables" eintragen.');
  }
  return v;
};
return [{
  json: {
    // ── aus der Data Table pw_config ──
    // Dieser Workflow verschickt keine Mail und braucht deshalb nur die
    // Paperless-Adresse für seine API-Aufrufe.
    paperless_url: pw('paperless_url')
  }
}];

// Dokument-ID aus dem Paperless-Webhook holen.
// Body kann { doc_id }, { id } oder { doc_url } enthalten.
const body = $('Webhook').first().json.body ?? {};
let id = body.doc_id ?? body.id;
if (!id && body.doc_url) {
  id = String(body.doc_url).match(/\/documents\/(\d+)/)?.[1];
}
if (!id) throw new Error('Keine doc_id/doc_url im Webhook-Body');
return [{ json: { id: Number(id) } }];

const doc = $input.first().json;
const content = (doc.content ?? '').trim();
if (!content) throw new Error('Dokument hat keinen Text (content leer)');
return [{ json: { id: doc.id, content, existingCustomFields: doc.custom_fields ?? [] } }];

// ============================================================
// KONFIGURATION
const MISTRAL_MODEL = 'mistral-small-latest';
const MAX_CONTENT_CHARS = 15000;
// ============================================================

const src = $('Extract content').first().json;

const SYSTEM_PROMPT = `Du bist ein Assistent zur Datenextraktion aus Verträgen in einem Paperless-Dokumentenmanagementsystem. Du bekommst den OCR-Volltext eines Vertrags und extrahierst Vertragslaufzeit und Kündigungsfrist.

Zu extrahierende Felder:
- "vertragsende": Datum, zu dem der Vertrag regulär endet bzw. sich das nächste Mal automatisch verlängert (nächstmöglicher Kündigungstermin), Format YYYY-MM-DD. Bei unbefristeten Verträgen ohne festen Termin: null.
- "frist_wert": Kündigungsfrist als Zahl (z. B. 3 bei "drei Monate zum Vertragsende"). null, wenn keine Frist genannt ist.
- "frist_einheit": Einheit der Kündigungsfrist: "tage", "wochen" oder "monate". null, wenn keine Frist genannt ist.
- "kuendigungsfrist_text": Die Kündigungsfrist wörtlich wie im Vertrag (z. B. "3 Monate zum Laufzeitende"). null, wenn nicht genannt.

Regeln:
- Erfinde niemals Werte; bist du unsicher, gib null zurück
- Ist das Dokument gar kein Vertrag, gib überall null zurück
- Verlängert sich der Vertrag automatisch und das genannte Ende liegt in der Vergangenheit, gib das im Vertrag genannte Datum trotzdem an; die Berechnung übernimmt das System

Antworte ausschließlich mit gültigem JSON in genau diesem Format und ohne weitere Felder:
{"vertragsende": "YYYY-MM-DD", "frist_wert": 3, "frist_einheit": "monate", "kuendigungsfrist_text": "..."}
(jeder Wert kann auch null sein)`;

const contentExcerpt = src.content.slice(0, MAX_CONTENT_CHARS);
const userContent = `OCR-Volltext des Vertrags (Auszug, ggf. gekürzt):\n---\n${contentExcerpt}\n---\n\nExtrahiere nun die Felder und antworte als JSON.`;

return [{
  json: {
    id: src.id,
    existingCustomFields: src.existingCustomFields,
    mistralBody: {
      model: MISTRAL_MODEL,
      response_format: { type: 'json_object' },
      temperature: 0,
      max_tokens: 300,
      messages: [
        { role: 'system', content: SYSTEM_PROMPT },
        { role: 'user', content: userContent },
      ],
    },
  },
}];

// Mistral-Antwort parsen und den spätesten Kündigungstermin berechnen.
// Die Datumsrechnung passiert bewusst hier in JS und nicht im LLM,
// weil LLMs sich bei Datumsarithmetik gern verrechnen.
const src = $('Prepare extraction').first().json;
const aiItem = $input.first().json;

let raw = aiItem?.choices?.[0]?.message?.content;
if (typeof raw !== 'string' || raw.trim() === '') {
  throw new Error('Keine Antwort von Mistral erhalten: ' + JSON.stringify(aiItem).slice(0, 500));
}
raw = raw.trim().replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/, '').trim();
let parsed;
try {
  parsed = JSON.parse(raw);
} catch {
  throw new Error('Mistral-Antwort ist kein gültiges JSON: ' + raw.slice(0, 500));
}

// Werte säubern und validieren.
let vertragsende = typeof parsed.vertragsende === 'string' ? parsed.vertragsende.trim() : null;
if (vertragsende && !/^\d{4}-\d{2}-\d{2}$/.test(vertragsende)) vertragsende = null;
const fristWert = typeof parsed.frist_wert === 'number' && parsed.frist_wert > 0 ? parsed.frist_wert : null;
const fristEinheit = ['tage', 'wochen', 'monate'].includes(parsed.frist_einheit) ? parsed.frist_einheit : null;
let fristText = typeof parsed.kuendigungsfrist_text === 'string' ? parsed.kuendigungsfrist_text.trim() : null;
if (fristText === '' || (fristText && fristText.toLowerCase() === 'null')) fristText = null;

// Kündigen bis = Vertragsende minus Kündigungsfrist.
let kuendigenBis = null;
if (vertragsende && fristWert && fristEinheit) {
  const d = new Date(vertragsende + 'T12:00:00');
  if (fristEinheit === 'monate') d.setMonth(d.getMonth() - fristWert);
  if (fristEinheit === 'wochen') d.setDate(d.getDate() - fristWert * 7);
  if (fristEinheit === 'tage') d.setDate(d.getDate() - fristWert);
  kuendigenBis = d.toISOString().slice(0, 10);
}

const has_result = !!(vertragsende || fristText);

return [{
  json: {
    id: src.id,
    existingCustomFields: src.existingCustomFields,
    has_result,
    vertragsende,
    kuendigungsfrist_text: fristText,
    kuendigen_bis: kuendigenBis,
  },
}];

const entityData = $('Parse + Frist berechnen').first().json;
const allFields = $input.first().json.results ?? [];

function findFieldId(name) {
  const field = allFields.find(f => String(f.name).toLowerCase() === name.toLowerCase());
  return field ? field.id : null;
}

// Paperless-Custom-Field -> extrahierter Wert (nur nicht-leere Werte schreiben).
const FIELD_VALUES = {
  'Vertragsende': entityData.vertragsende,
  'Kündigungsfrist': entityData.kuendigungsfrist_text,
  'Kündigen bis': entityData.kuendigen_bis,
};

const updates = [];
for (const [name, value] of Object.entries(FIELD_VALUES)) {
  if (value === null || value === undefined) continue;
  const fieldId = findFieldId(name);
  if (!fieldId) {
    throw new Error('Custom field "' + name + '" nicht in Paperless gefunden. Bitte unter Einstellungen > Benutzerdefinierte Felder anlegen (Vertragsende/Kündigen bis: Typ Datum, Kündigungsfrist: Typ Text).');
  }
  updates.push({ fieldId, value });
}

// Vorhandene Custom-Field-Werte behalten, nur die extrahierten überschreiben.
const updateIds = new Set(updates.map(u => u.fieldId));
const existingFields = entityData.existingCustomFields ?? [];
const otherFields = existingFields.filter(f => !updateIds.has(f.field));
const customFields = [
  ...otherFields,
  ...updates.map(u => ({ field: u.fieldId, value: u.value })),
];

return [{ json: { id: entityData.id, customFields, vertragsende: entityData.vertragsende, kuendigungsfrist: entityData.kuendigungsfrist_text, kuendigen_bis: entityData.kuendigen_bis } }];
